// Host test for cft_capnp.h / cft_rpc.h. Vectors were generated by cloudflared's own Go capnp library
// (upstream esp-cf-tunnel fixtures), so they are an independent oracle for the reader.
#include <cstdio>
#include <cstdlib>
#include "../../components/cloudflare_tunnel/cft_rpc.h"
#include "rpc_vectors.h"
using namespace cft;
static int checks;
#define CHECK(x) do { ++checks; if (!(x)) { fprintf(stderr, "FAIL %d: %s\n", __LINE__, #x); exit(1); } } while (0)
#define ARR(x) Bytes{x, sizeof(x)}
static Credentials cred;
static RpcOptions opt;
static const uint8_t ip[] = {192, 0, 2, 1};
static void setup() {
  memcpy(cred.account_tag, "0123456789abcdef0123456789abcdef", 33);
  cred.secret_len = 36;
  for (int i = 0; i < 36; i++) cred.secret[i] = i;
  for (int i = 0; i < 16; i++) cred.tunnel_id[i] = opt.connector_id[i] = i;
  opt.local_ip = ARR(ip);
  opt.version = "esp-cf-test"; opt.arch = "host-test";
  opt.connection_index = 2; opt.previous_attempts = 3;
  opt.features = FEATURE_REMOTE_CONFIG | FEATURE_SERIALIZED_HEADERS;
}
static uint64_t kind(Bytes f) { Reader r; CHECK(r.init(f)); return Reader::u(r.root(), 0, 2); }
static bool eq(Bytes b, const void *p, size_t n) { return b.len == n && !memcmp(b.ptr, p, n); }
// Decode our own register request field by field against the schema (reader is validated by the Go vectors).
static void check_register(Bytes f) {
  Reader rd; CHECK(rd.init(f));
  Obj m = rd.root(); CHECK(Reader::u(m, 0, 2) == 2);
  Obj call = rd.field(m, 0);
  CHECK(Reader::u(call, 0, 4) == 1 && Reader::u(call, 4, 2) == 0 && Reader::u(call, 8, 8) == 0xf71695ec7fe85497ull);
  Obj tgt = rd.field(call, 0); CHECK(Reader::u(tgt, 0, 4) == 37 && Reader::u(tgt, 4, 2) == 0);
  Obj params = rd.field(rd.field(call, 1), 0);
  CHECK(Reader::u(params, 0, 1) == 2);
  Obj auth = rd.field(params, 0);
  CHECK(eq(rd.blob(auth, 0, true), cred.account_tag, 32) && eq(rd.blob(auth, 1), cred.secret, 36));
  CHECK(eq(rd.blob(params, 1), cred.tunnel_id, 16));
  Obj o = rd.field(params, 2); CHECK(Reader::u(o, 0, 1) == 0 && Reader::u(o, 2, 1) == 3 && Reader::u(o, 1, 1) == 0);
  CHECK(eq(rd.blob(o, 1), ip, 4));
  Obj c = rd.field(o, 0);
  CHECK(eq(rd.blob(c, 0), opt.connector_id, 16) && eq(rd.blob(c, 2, true), "esp-cf-test", 11) && eq(rd.blob(c, 3, true), "host-test", 9));
}
static void registering(Rpc &r, uint8_t *out) {
  size_t n; r.reset();
  CHECK(r.begin(out, RPC_TX_MAX, &n) == OK);
  CHECK(r.receive(ARR(rpc_bootstrap), out, RPC_TX_MAX, &n) == OK);
  CHECK(r.state == READY && r.capability == 37);
  CHECK(r.register_connection(cred, opt, out, RPC_TX_MAX, &n) == OK && r.state == REGISTERING);
}
int main(int argc, char **argv) {
  setup();
  static Rpc r; uint8_t out[RPC_TX_MAX]; size_t n;
  Bytes boot[] = {ARR(rpc_bootstrap), ARR(rpc_bootstrap_multi)}, succ[] = {ARR(rpc_success), ARR(rpc_success_multi)};
  for (int i = 0; i < 2; i++) {
    r.reset();
    CHECK(r.begin(out, sizeof out, &n) == OK && n == 48 && kind({out, n}) == 8);
    CHECK(r.begin(out, sizeof out, &n) == ERR_STATE && n == 0);
    CHECK(r.receive(boot[i], out, sizeof out, &n) == OK && r.state == READY && kind({out, n}) == 4);
    CHECK(r.register_connection(cred, opt, out, sizeof out, &n) == OK && kind({out, n}) == 2);
    check_register({out, n});
    if (argc > 1 && i == 0) { fwrite(out, 1, n, fopen(argv[1], "wb")); }
    CHECK(r.receive(succ[i], out, sizeof out, &n) == OK);
    CHECK(r.state == REGISTERED && r.remotely_managed && !strcmp(r.location, "SOF"));
    CHECK(!memcmp(r.connection_id, cred.tunnel_id, 16));
    CHECK(r.unregister(out, sizeof out, &n) == OK && r.state == UNREGISTERING);
    CHECK(r.receive(ARR(rpc_unregister_multi), out, sizeof out, &n) == OK && r.state == CLOSED);
    CHECK(!r.have_capability && n == 80 && kind({out, 40}) == 4 && kind({out + 40, 40}) == 6);
  }
  registering(r, out);
  CHECK(r.receive(ARR(rpc_retry_multi), out, sizeof out, &n) == OK && r.state == REJECTED && r.should_retry && r.retry_after_ms == 1501);
  registering(r, out);
  CHECK(r.receive(ARR(rpc_permanent), out, sizeof out, &n) == OK && r.state == REJECTED && !r.should_retry);
  registering(r, out);
  CHECK(r.receive(ARR(rpc_negative), out, sizeof out, &n) == OK && r.retry_after_ms == 0);
  Bytes bad[] = {ARR(rpc_wrong_question), ARR(rpc_local), ARR(rpc_exception), ARR(rpc_abort)};
  for (auto &b : bad) {
    registering(r, out);
    Result rr = r.receive(b, out, sizeof out, &n); if (rr == OK) fprintf(stderr, "bad vector %d accepted\n", (int) (&b - bad));
    CHECK(rr != OK && r.state == FAILED);
    CHECK(r.receive(ARR(rpc_success), out, sizeof out, &n) == ERR_STATE && n == 0);
  }
  r.reset(); CHECK(r.begin(out, sizeof out, &n) == OK);
  CHECK(r.receive(ARR(rpc_promise_multi), out, sizeof out, &n) == ERR_UNSUPPORTED && r.state == FAILED && kind({out, n}) == 1);
  // truncation and single-bit flips must never crash and must either succeed or fail cleanly
  const Bytes seeds[] = {ARR(rpc_bootstrap), ARR(rpc_bootstrap_multi), ARR(rpc_success), ARR(rpc_success_multi), ARR(rpc_retry_multi),
                         ARR(rpc_permanent), ARR(rpc_exception), ARR(rpc_promise_multi), ARR(rpc_unregister_multi)};
  for (size_t s = 0; s < 9; s++) {
    uint8_t f[512];
    for (size_t cut = 0; cut < seeds[s].len; cut++)
      for (int flip = -1; flip < 8; flip++) {
        memcpy(f, seeds[s].ptr, seeds[s].len);
        size_t len = seeds[s].len;
        if (flip < 0) len = cut; else f[cut] ^= 1u << flip;
        r.reset();
        r.state = s < 2 || s == 7 ? BOOTSTRAPPING : s == 8 ? UNREGISTERING : REGISTERING;
        r.have_capability = s >= 2; r.capability = 37;
        Result rc = r.receive({f, len}, out, sizeof out, &n);
        CHECK(n <= sizeof out && (rc == OK || r.state == FAILED));
      }
  }
  printf("ok %d checks\n", checks);
}
